import React, { useEffect, useState } from "react";
import "./MyEvents.css";
import headerimage from "../assets/MyEventsHeader.png";

const MyEvents = () => {
  const [events, setEvents] = useState([]);

  // Fake data for now — replace with API or state later
  const mockPurchasedEvents = [
    { id: 1, name: "Music Festival", date: "2025-10-20", location: "Toronto" },
    { id: 2, name: "Art Expo", date: "2025-11-05", location: "Montreal" },
    { id: 3, name: "Tech Conference", date: "2025-12-10", location: "Vancouver" },
  ];

  useEffect(() => {
    // Simulate fetching purchased events
    setEvents(mockPurchasedEvents);
  }, []);

  return (
    <div className="my-events-container">
      <div className="header-image"></div><h1>My Events</h1>
      {events.length === 0 ? (
        <p>You haven’t purchased any events yet.</p>
      ) : (
        <ul className="event-list">
          {events.map((event) => (
            <li key={event.id} className="event-item">
              <h3>{event.name}</h3>
              <p>Date: {event.date}</p>
              <p>Location: {event.location}</p>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default MyEvents;
